basicCode.vanilla:
import { createMessageQueue } from '@/components/ui/message-queue';

const queue = createMessageQueue({
  labels,
  messages: [
    { id: 'm1', text: 'Manda o resumo de ontem', state: 'sending' },
    { id: 'm2', text: 'E o prazo?', state: 'waiting' },
  ],
  onWithdraw: (message) => withdraw(message.id),
});

document.querySelector('#app')?.append(queue);

basicCode.react:
import { MessageQueue } from "@/components/ui/message-queue";

<MessageQueue
  labels={labels}
  messages={[
    { id: "m1", text: "Manda o resumo de ontem", state: "sending" },
    { id: "m2", text: "E o prazo?", state: "waiting" },
  ]}
  onWithdraw={(message) => withdraw(message.id)}
/>

extensibilityCode.web:
// Quem decide se pode retirar é o vocabulário compartilhado, e não a tela.
// Duas palavras, e a segunda tira o botão: o que já saiu não volta.
import { canWithdraw } from '@shared/primitives/chat-protocol';

canWithdraw({ text: 'E o prazo?', state: 'waiting' });  // true
canWithdraw({ text: 'E o prazo?', state: 'sending' });  // false

customizationCode.web:
.nds-composer-queue-item {
  max-inline-size: 32rem;
}

/* A fila mais colada ao campo, quando quem consome já empilha os dois. */
.nds-composer-queue {
  margin-block-end: var(--spacing-1);
}

